/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
# motion map: difference between frames
for t in [0,12,24,36,48,60,72,84,95]:
    if t==0: diff=np.zeros((144,256))
    else: diff=np.abs(d[t]-d[t-1]).sum(2)
    ys,xs=np.where(diff>40)
    if len(ys): print(t,'changed',len(ys),'bbox y',ys.min(),ys.max(),'x',xs.min(),xs.max())
    else: print(t,'no change')
\""

