import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
for t in range(0,96,4):
    f=d[t]; r,g,b=f[...,0],f[...,1],f[...,2]
    red=(r>g+30)&(r>b+30)
    ys,xs=np.where(red)
    if len(ys): print(t,'red n=',len(ys),'y',ys.min(),ys.max(),'x',xs.min(),xs.max(),'meanx',xs.mean().round(1))
    else: print(t,'no red')
\""
